body {
  margin: 0;
  padding: 40px;
  background: var(--color-paper);
  color: var(--color-ink);
  font: 16px var(--font-body);
}
h1 {
  font:
    56px Georgia,
    serif;
  letter-spacing: -2px;
}
button {
  background: var(--color-accent);
  color: var(--color-on-accent);
  padding: 12px 20px;
  border: 0;
  border-radius: var(--radius-control);
  font: inherit;
}

body {
  margin: 0;
  padding: 32px;
  font: 16px system-ui;
  background: var(--color-paper);
}
.row {
  display: flex;
  gap: 16px;
  align-items: center;
  flex-wrap: wrap;
}
p {
  color: var(--color-ink);
}
